<?php
// Included by run.php (after odoo_tests.php, whose API server and api() helper are reused):
// gate <-> weighbridge data flow in both directions, outside weighbridge slips, product-category analytics.
$cols = fn(string $t) => array_column(Db::all("PRAGMA table_info($t)"), 'name');
echo "Gate <-> weighbridge: schema and categories\n";
t('schema 7 columns exist', in_array('category', $cols('materials'), true) && in_array('ext_net_kg', $cols('gate_entries'), true) && in_array('wb_net_kg', $cols('gate_entries'), true) && in_array('source', $cols('weighments'), true));
foreach (['Iron Ore' => 'Raw Material', 'Coal' => 'Fuel', 'Cement' => 'Finished goods'] as $m => $c) { Db::q('INSERT OR IGNORE INTO materials(name) VALUES (?)', [$m]); Db::q('UPDATE materials SET category = ? WHERE name = ?', [$c, $m]); }
t('category list ends with Uncategorised', array_slice(Analytics::categories(), -1) === ['Uncategorised'] && in_array('Fuel', Analytics::categories(), true));

echo "Gate -> weighbridge (what the guard typed reaches the ticket)\n";
Settings::set('gate_require_entry', 'off'); Settings::reset();
$e1 = GateEntries::register(['vehicle_no' => 'GATE1', 'purpose' => 'DISPATCH', 'party' => 'Gate Party', 'material' => 'Coal', 'challan_no' => 'CH-9', 'driver' => 'Raju'], 0, false)['id'];
setLive(30000, true); $g1 = Weighment::create(['vehicle_no' => 'GATE1', 'first_type' => 'GROSS', 'direction' => '', 'scale_id' => 1], null);
$w = Db::one('SELECT * FROM weighments WHERE id = ?', [$g1]);
t('blank party / material / challan / driver come from the gate entry', $w['party'] === 'Gate Party' && $w['material'] === 'Coal' && $w['challan_no'] === 'CH-9' && $w['driver'] === 'Raju');
t('direction "Auto" follows the gate purpose (dispatch -> OUTWARD)', $w['direction'] === 'OUTWARD' && $w['source'] === 'LOCAL');
$ge = Db::one('SELECT * FROM gate_entries WHERE id = ?', [$e1]);
t('weighbridge -> gate: entry shows the open ticket', $ge['wb_ticket_no'] === $w['ticket_no'] && $ge['wb_status'] === 'OPEN' && $ge['wb_net_kg'] === null);
setLive(9000, true); Weighment::second($g1, null, 1);
$ge = Db::one('SELECT * FROM gate_entries WHERE id = ?', [$e1]);
t('weighbridge -> gate: net weight written back when the ticket closes', $ge['wb_status'] === 'CLOSED' && (float)$ge['wb_net_kg'] === 21000.0);
$e2 = GateEntries::register(['vehicle_no' => 'GATE2', 'purpose' => 'DELIVERY'], 0, false)['id'];
setLive(30000, true); $g2 = Weighment::create(['vehicle_no' => 'GATE2', 'first_type' => 'GROSS', 'direction' => 'OUTWARD', 'party' => 'Typed Party', 'material' => 'Iron Ore', 'scale_id' => 1], null);
t('an explicit direction wins over the gate purpose', Db::val('SELECT direction FROM weighments WHERE id = ?', [$g2]) === 'OUTWARD');
t('what the operator typed fills the blanks of the gate entry', Db::val('SELECT party FROM gate_entries WHERE id = ?', [$e2]) === 'Typed Party' && Db::val('SELECT material FROM gate_entries WHERE id = ?', [$e2]) === 'Iron Ore');
Weighment::cancel($g2, 'test');
t('cancelling the ticket clears the write-back', Db::val('SELECT wb_ticket_no FROM gate_entries WHERE id = ?', [$e2]) === null);
$e3 = GateEntries::register(['vehicle_no' => 'GATE3', 'purpose' => 'DELIVERY'], 0, false)['id'];
setLive(30000, true); $g3 = Weighment::create(['vehicle_no' => 'GATE3', 'first_type' => 'GROSS', 'scale_id' => 1], null);
t('no direction at all + delivery -> INWARD', Db::val('SELECT direction FROM weighments WHERE id = ?', [$g3]) === 'INWARD');
setLive(9000, true); Weighment::second($g3, null, 1);

echo "Outside weighbridge slips (gate -> weighbridge)\n";
$base = ['vehicle_no' => 'EXT1', 'weighbridge' => 'Shiv Kanta', 'slip_no' => 'S-1', 'gross_kg' => '38,400', 'tare_kg' => 14200, 'material' => 'Iron Ore', 'party' => 'Ext Party', 'direction' => 'INWARD', 'weighed_at' => '2026-10-12 09:40:00'];
$r = GateEntries::externalSlip($base);
t('slip recorded: net = gross - tare, ticket + entry created', !$r['duplicate'] && $r['net_kg'] === 24200.0 && $r['entry_no'] !== '' && str_starts_with($r['ticket_no'], 'WB'), json_encode($r));
$w = Db::one('SELECT * FROM weighments WHERE id = ?', [$r['ticket_id']]);
t('ticket is CLOSED, source EXTERNAL, slip time kept, linked to the entry', $w['status'] === 'CLOSED' && $w['source'] === 'EXTERNAL' && $w['first_at'] === '2026-10-12 09:40:00' && (int)$w['gate_entry_id'] === $r['entry_id'] && (float)$w['net_kg'] === 24200.0 && str_contains($w['remarks'], 'OUTSIDE WEIGHBRIDGE'));
$ge = Db::one('SELECT * FROM gate_entries WHERE id = ?', [$r['entry_id']]);
t('gate entry carries the slip (weighbridge, slip no, weights)', $ge['status'] === 'INSIDE' && $ge['ext_wb_name'] === 'Shiv Kanta' && $ge['ext_slip_no'] === 'S-1' && (float)$ge['ext_net_kg'] === 24200.0 && $ge['party'] === 'Ext Party');
$nt = (int)Db::val('SELECT COUNT(*) FROM weighments');
$r2 = GateEntries::externalSlip($base);
t('same slip again is idempotent (same ticket, nothing new)', $r2['duplicate'] && $r2['ticket_no'] === $r['ticket_no'] && (int)Db::val('SELECT COUNT(*) FROM weighments') === $nt);
$r3 = GateEntries::externalSlip(['vehicle_no' => 'EXT2', 'weighbridge' => 'Other Kanta', 'slip_no' => 'S-1', 'gross_kg' => 30000, 'tare_kg' => 10000, 'material' => 'Iron Ore', 'direction' => 'INWARD']);
t('same slip number at ANOTHER weighbridge is a different slip', !$r3['duplicate'] && $r3['ticket_no'] !== $r['ticket_no']);
$r4 = GateEntries::externalSlip(['vehicle_no' => 'EXT3', 'weighbridge' => 'Shiv Kanta', 'slip_no' => 'S-3', 'gross_kg' => 30000, 'net_kg' => 20000]);
t('gross + net -> tare derived', (float)Db::val('SELECT tare_kg FROM weighments WHERE id = ?', [$r4['ticket_id']]) === 10000.0);
$bad = fn(array $x) => (string)throws(fn() => GateEntries::externalSlip($x + ['vehicle_no' => 'EXTBAD', 'weighbridge' => 'W', 'slip_no' => 'B' . uniqid()]));
t('gross <= tare refused', str_contains($bad(['gross_kg' => 100, 'tare_kg' => 200]), 'greater'));
t('net that does not fit gross - tare refused', str_contains($bad(['gross_kg' => 30000, 'tare_kg' => 10000, 'net_kg' => 25000]), 'Check the figures'));
t('no weights refused', str_contains($bad([]), 'gross and tare'));
t('only a gross weight refused', str_contains($bad(['gross_kg' => 30000]), 'gross and tare'));
t('absurd weight refused', str_contains($bad(['gross_kg' => 900000, 'tare_kg' => 10000]), 'look wrong'));
t('slip number required', str_contains((string)throws(fn() => GateEntries::externalSlip(['vehicle_no' => 'X1', 'weighbridge' => 'W', 'gross_kg' => 2, 'tare_kg' => 1])), 'slip number'));
t('weighbridge name required', str_contains((string)throws(fn() => GateEntries::externalSlip(['vehicle_no' => 'X1', 'slip_no' => '1', 'gross_kg' => 2, 'tare_kg' => 1])), 'weighbridge'));
t('future slip time refused', str_contains($bad(['gross_kg' => 30000, 'tare_kg' => 10000, 'weighed_at' => date('Y-m-d H:i:s', time() + 86400 * 3)]), 'not valid'));
t('refused slips leave nothing behind', (int)Db::val("SELECT COUNT(*) FROM weighments WHERE vehicle_no = 'EXTBAD'") === 0 && (int)Db::val("SELECT COUNT(*) FROM gate_entries WHERE vehicle_no = 'EXTBAD'") <= 1);
Db::q("INSERT OR IGNORE INTO vehicles(reg_no) VALUES ('EXTBLK')"); Db::q("UPDATE vehicles SET blocked = 1, block_reason = 'test' WHERE reg_no = 'EXTBLK'");
t('blocked vehicle: slip refused', str_contains((string)throws(fn() => GateEntries::externalSlip(['vehicle_no' => 'EXTBLK', 'weighbridge' => 'W', 'slip_no' => 'K1', 'gross_kg' => 30000, 'tare_kg' => 10000])), 'BLOCKED') && (int)Db::val("SELECT COUNT(*) FROM weighments WHERE vehicle_no = 'EXTBLK'") === 0);
t('slip for a different vehicle than the chosen entry refused', str_contains((string)throws(fn() => GateEntries::externalSlip(['vehicle_no' => 'OTHER99', 'weighbridge' => 'W', 'slip_no' => 'Z1', 'gross_kg' => 30000, 'tare_kg' => 10000], $r['entry_id'])), 'entry is for'));
Settings::set('gate_exit_policy', 'block'); Settings::reset();
$ex = GateEntries::exit($r['entry_id'], 0, false);
t('exit allowed on the outside slip alone (counts as the completed weighment)', Db::val('SELECT status FROM gate_entries WHERE id = ?', [$r['entry_id']]) === 'EXITED');
Settings::set('gate_exit_policy', 'warn'); Settings::reset();
$ge4 = GateEntries::register(['vehicle_no' => 'EXT1', 'purpose' => 'DELIVERY', 'material' => 'Iron Ore'], 0, false)['id'];   // truck comes back: new entry, old slip untouched

echo "Factory weighbridge vs outside slip\n";
setLive(40000, true); $f1 = Weighment::create(['vehicle_no' => 'EXT2', 'first_type' => 'GROSS', 'scale_id' => 1], null);
setLive(15000, true); Weighment::second($f1, null, 1);
$en = Db::one('SELECT * FROM gate_entries WHERE id = ?', [$r3['entry_id']]);
$v = GateEntries::variance($en);
t('factory 25000 vs slip 20000: difference flagged', $v && !$v['ok'] && (float)$v['diff_kg'] === 5000.0 && (float)$en['wb_net_kg'] === 25000.0 && (float)$en['ext_net_kg'] === 20000.0, json_encode($v));
t('both tickets stay linked to the entry', (int)Db::val('SELECT COUNT(*) FROM weighments WHERE gate_entry_id = ?', [$r3['entry_id']]) === 2);
$r5 = GateEntries::externalSlip(['vehicle_no' => 'EXT5', 'weighbridge' => 'Shiv Kanta', 'slip_no' => 'S-5', 'gross_kg' => 30000, 'tare_kg' => 10000]);
setLive(30010, true); $f5 = Weighment::create(['vehicle_no' => 'EXT5', 'first_type' => 'GROSS', 'scale_id' => 1], null);
setLive(10000, true); Weighment::second($f5, null, 1);
$v5 = GateEntries::variance(Db::one('SELECT * FROM gate_entries WHERE id = ?', [$r5['entry_id']]));
t('20010 vs 20000 is within the tolerance', $v5 && $v5['ok'] && (float)$v5['diff_kg'] === 10.0);
t('no variance while only one side exists', GateEntries::variance(Db::one('SELECT * FROM gate_entries WHERE id = ?', [$r4['entry_id']])) === null);
t('Analytics::variances lists only the bad one', array_column(Analytics::variances(['from' => date('Y-m-d'), 'to' => date('Y-m-d')]), 'vehicle_no') === ['EXT2']);
Settings::set('ext_tol_pct', '30'); Settings::reset();
t('tolerance is a setting', GateEntries::variance(Db::one('SELECT * FROM gate_entries WHERE id = ?', [$r3['entry_id']]))['ok'] === true);
Settings::set('ext_tol_pct', '1'); Settings::reset();

echo "Outside slips flow to Odoo like any ticket\n";
Settings::set('odoo_enabled', '1'); Settings::reset();
$r6 = GateEntries::externalSlip(['vehicle_no' => 'EXT6', 'weighbridge' => 'Shiv Kanta', 'slip_no' => 'S-6', 'gross_kg' => 31000, 'tare_kg' => 11000, 'material' => 'Coal']);
t('queued for Odoo when the transfer is on', Db::val('SELECT odoo_status FROM weighments WHERE id = ?', [$r6['ticket_id']]) === 'PENDING');
$o = OdooSync::syncPending();
t('and delivered (no scale on the ticket is fine)', Db::val('SELECT odoo_status FROM weighments WHERE id = ?', [$r6['ticket_id']]) === 'SYNCED' && $o['failed'] === 0, json_encode($o));
Settings::set('odoo_enabled', '0'); Settings::reset();

echo "Analytics by product category\n";
$mk = function (string $veh, string $mat, string $dir, float $net, string $day, string $slip) {
    return GateEntries::externalSlip(['vehicle_no' => $veh, 'weighbridge' => 'AN Kanta', 'slip_no' => $slip, 'gross_kg' => $net + 10000, 'tare_kg' => 10000, 'material' => $mat, 'direction' => $dir, 'weighed_at' => "$day 10:00:00"]);
};
$mk('AN1', 'Iron Ore', 'INWARD', 24000, '2026-01-05', 'a1'); $mk('AN2', 'IRON ORE', 'INWARD', 26000, '2026-01-05', 'a2'); $mk('AN3', 'Coal', 'INWARD', 10000, '2026-01-05', 'a3');
$mk('AN4', 'Cement', 'OUTWARD', 30000, '2026-01-05', 'a4'); $mk('AN5', 'Mystery', 'INWARD', 5000, '2026-01-05', 'a5'); $mk('AN7', 'Iron Ore', 'INWARD', 8000, '2026-01-07', 'a7');
$c6 = $mk('AN6', 'Coal', 'INWARD', 18000, '2026-01-06', 'a6'); Weighment::cancel($c6['ticket_id'], 'cancelled load');
$F = ['from' => '2026-01-01', 'to' => '2026-01-31'];
$by = array_column(Analytics::byCategory($F), null, 'category');
t('categories: Raw Material 3 in / 58 t (case-insensitive material match)', ($by['Raw Material']['in_trucks'] ?? 0) === 3 && ($by['Raw Material']['in_kg'] ?? 0) === 58000.0);
t('categories: Fuel 1 in / 10 t (cancelled load not counted)', ($by['Fuel']['in_trucks'] ?? 0) === 1 && ($by['Fuel']['in_kg'] ?? 0) === 10000.0);
t('categories: Finished goods 1 out / 30 t', ($by['Finished goods']['out_trucks'] ?? 0) === 1 && ($by['Finished goods']['out_kg'] ?? 0) === 30000.0 && $by['Finished goods']['in_trucks'] === 0);
t('categories: unknown material -> Uncategorised', ($by['Uncategorised']['in_kg'] ?? 0) === 5000.0);
$tot = Analytics::totals(array_values($by));
t('totals and balance', $tot['in_trucks'] === 5 && $tot['out_trucks'] === 1 && $tot['in_kg'] === 73000.0 && $tot['out_kg'] === 30000.0 && $tot['balance_kg'] === 43000.0 && $tot['ext_trucks'] === 6);
t('average tonnes per truck', abs($by['Raw Material']['avg_in_kg'] - 58000 / 3) < 0.01 && $by['Finished goods']['avg_in_kg'] === null);
$k = Analytics::byCategory($F + ['category' => 'Fuel']);
t('category filter', count($k) === 1 && $k[0]['category'] === 'Fuel');
t('Uncategorised can be filtered too', count(Analytics::byCategory($F + ['category' => 'Uncategorised'])) === 1);
t('source filter: LOCAL tickets only -> none in January', Analytics::byCategory($F + ['source' => 'LOCAL']) === []);
t('source filter: outside slips only -> everything', Analytics::totals(Analytics::byCategory($F + ['source' => 'EXTERNAL']))['in_trucks'] === 5);
t('date range excludes other days', Analytics::totals(Analytics::byCategory(['from' => '2026-01-06', 'to' => '2026-01-31']))['in_trucks'] === 1);
$d = Analytics::daily($F);
t('daily: every day of the range is present', count($d) === 31 && $d[0]['date'] === '2026-01-01' && $d[30]['date'] === '2026-01-31');
t('daily: 5 Jan has 4 in / 1 out, 7 Jan 1 in, others empty', $d[4]['in_trucks'] === 4 && $d[4]['out_trucks'] === 1 && $d[4]['in_kg'] === 65000.0 && $d[6]['in_trucks'] === 1 && $d[5]['in_trucks'] === 0);
t('daily: category filter applies', array_sum(array_column(Analytics::daily($F + ['category' => 'Fuel']), 'in_trucks')) === 1);
$top = Analytics::topMaterials($F);
t('top materials ordered by tonnes', $top[0]['material'] === 'Iron Ore' && (float)$top[0]['kg'] === 32000.0 && $top[0]['category'] === 'Raw Material');
t('bad dates are ignored, not injected', is_array(Analytics::byCategory(['from' => "2026-01-01' OR 1=1 --", 'to' => 'x'])));
Db::q('INSERT OR IGNORE INTO materials(name, category) VALUES (?, ?)', ['Lignite', 'Solid Fuel']);
Db::q("UPDATE gate_entries SET in_at = ?, material = 'Lignite' WHERE id = ?", [date('Y-m-d H:i:s', time() - 7200), $e1]);
GateEntries::exit($e1, 0, false);
$gt = array_column(Analytics::gate(['from' => date('Y-m-d', time() - 7200), 'to' => date('Y-m-d')]), null, 'category');
t('gate register: Solid Fuel exit after 2 h on site', isset($gt['Solid Fuel']) && $gt['Solid Fuel']['exits'] === 1 && $gt['Solid Fuel']['avg_min'] > 119 && $gt['Solid Fuel']['avg_min'] < 122, json_encode($gt['Solid Fuel'] ?? null));
t('gate register counts deliveries / dispatches', array_sum(array_column($gt, 'dispatches')) >= 1 && array_sum(array_column($gt, 'entries')) === (int)Db::val("SELECT COUNT(*) FROM gate_entries WHERE status <> 'CANCELLED' AND substr(in_at,1,10) >= ?", [date('Y-m-d', time() - 7200)]));

echo "Odoo product categories\n";
Db::q("INSERT OR IGNORE INTO materials(name, category) VALUES ('Limestone', 'Custom')"); Db::q("UPDATE materials SET category = 'Custom' WHERE name = 'Limestone'");
Settings::set('odoo_enabled', '1'); Settings::reset();
(new OdooSync(Settings::all()))->pullMasters();
t('product category pulled (last part of "All / Raw Materials / Ores")', Db::val("SELECT category FROM materials WHERE name = 'Iron Ore Lumps'") === 'Ores');
t('a category set in the weighbridge is never overwritten', Db::val("SELECT category FROM materials WHERE name = 'Limestone'") === 'Custom');
Settings::set('odoo_enabled', '0'); Settings::reset();

echo "REST API: gate and analytics\n";
Settings::set('api_write', '0'); Settings::reset();
$slip = ['vehicle_no' => 'API1', 'weighbridge' => 'Api Kanta', 'slip_no' => 'P-1', 'gross_kg' => 36000, 'tare_kg' => 12000, 'material' => 'Coal', 'party' => 'Api Party', 'direction' => 'INWARD'];
[$c] = api('POST', 'external_slips.php', $slip); t('slip push refused while writes are off -> 403', $c === 403);
[$c] = api('POST', 'external_slips.php', $slip, 'wrong'); t('slip push needs the token', $c === 401);
Settings::set('api_write', '1'); Settings::reset();
[$c, $j] = api('POST', 'external_slips.php', $slip);
t('slip push: ticket created', $c === 200 && $j['ok'] === true && $j['duplicate'] === false && $j['net_kg'] == 24000 && str_starts_with($j['ticket_no'], 'WB'), json_encode($j));
[$c, $j2] = api('POST', 'external_slips.php', $slip);
t('slip push again: same ticket, duplicate true, HTTP 200', $c === 200 && $j2['duplicate'] === true && $j2['ticket_no'] === $j['ticket_no']);
[$c, $j3] = api('POST', 'external_slips.php', array_merge($slip, ['gross_kg' => 5, 'slip_no' => 'x']));
t('slip push: bad data -> 422 with the reason', $c === 422 && str_contains($j3['error'], 'greater'), json_encode($j3));
[$c, $j4] = api('POST', 'external_slips.php', ['slips' => [['slip_no' => 'P-2', 'vehicle_no' => 'API2', 'weighbridge' => 'Api Kanta', 'gross_kg' => 30000, 'tare_kg' => 10000], ['slip_no' => 'P-3', 'vehicle_no' => 'API3', 'weighbridge' => 'Api Kanta', 'gross_kg' => 1, 'tare_kg' => 5]]]);
t('batch: one result per slip, the good one is stored', $c === 200 && $j4['ok'] === false && $j4['results'][0]['ok'] === true && $j4['results'][1]['ok'] === false && (int)Db::val("SELECT COUNT(*) FROM weighments WHERE ext_slip_no = 'P-2'") === 1);
[$c, $j] = api('GET', 'tickets.php?ticket_no=' . rawurlencode($j['ticket_no']));
t('tickets API tells outside slips apart', $j['ticket']['source'] === 'EXTERNAL' && $j['ticket']['ext_weighbridge'] === 'Api Kanta' && $j['ticket']['ext_slip_no'] === 'P-1');
[$c, $j] = api('GET', 'gate_entries.php?vehicle=API1');
t('gate_entries GET: entry with the outside slip', $c === 200 && $j['count'] === 1 && $j['entries'][0]['status'] === 'INSIDE' && $j['entries'][0]['ext_net_kg'] == 24000 && $j['entries'][0]['slip_variance_kg'] === null);
[$c, $j] = api('GET', 'gate_entries.php?vehicle=EXT2');
t('gate_entries GET: factory result and slip difference', $j['entries'][0]['wb_net_kg'] == 25000 && $j['entries'][0]['slip_variance_kg'] == 5000 && $j['entries'][0]['slip_ok'] === false);
[$c, $j] = api('POST', 'gate_entries.php', ['vehicle_no' => 'api 9', 'purpose' => 'DISPATCH', 'material' => 'Cement', 'party' => 'Buyer']);
t('gate_entries POST registers a vehicle', $c === 201 && $j['vehicle_no'] === 'API9' && $j['status'] === 'INSIDE');
[$c, $j] = api('POST', 'gate_entries.php', ['vehicle_no' => 'API9']); t('gate_entries POST: already inside -> 422', $c === 422 && str_contains($j['error'], 'already inside'));
[$c, $j] = api('POST', 'gate_entries.php', ['vehicle_no' => 'EXTBLK']); t('gate_entries POST: blocked vehicle -> 422', $c === 422 && str_contains($j['error'], 'BLOCKED'));
Settings::set('api_write', '0'); Settings::reset();
[$c] = api('POST', 'gate_entries.php', ['vehicle_no' => 'API10']); t('gate_entries POST needs writes on', $c === 403);
[$c, $j] = api('GET', 'analytics.php?from=2026-01-01&to=2026-01-31');
t('analytics API equals the page logic', $c === 200 && $j['totals']['in_trucks'] === 5 && $j['totals']['balance_kg'] == 43000 && count($j['by_category']) === 4 && count($j['daily']) === 31 && isset($j['gate'], $j['slip_variances'], $j['top_materials']));
[$c, $j] = api('GET', 'analytics.php?from=2026-01-01&to=2026-01-31&category=Fuel&source=EXTERNAL');
t('analytics API filters', $j['totals']['in_trucks'] === 1 && count($j['by_category']) === 1);
[$c, $j] = api('GET', 'ping.php'); t('ping lists the new endpoints', in_array('external_slips', $j['endpoints'], true) && in_array('analytics', $j['endpoints'], true));
[$c, $j] = api('GET', 'openapi.php', null, null); t('openapi describes them', isset($j['paths']['/api/v1/external_slips.php'], $j['paths']['/api/v1/gate_entries.php'], $j['paths']['/api/v1/analytics.php']));
